message.content:
{
  "claims": [
    {
      "text": "Monitor respiratory status closely with continuous pulse oximetry and reassess oxygen needs, given tachypnea (RR 22-27) and SpO2 92-97% on 2-3 L/min nasal cannula.",
      "action_type": "monitored",
      "target": "respiratory status"
    },
    {
      "text": "Obtain blood cultures and reassess for infection given leukocytosis (WBC 19 K/uL) and fever up to 99.7 F.",
      "action_type": "specimen_collected",
      "target": "blood cultures"
    },
    {
      "text": "Continue cardiac monitoring with ST segment monitoring and telemetry given tachycardia (HR up to 120 bpm) and need to assess for arrhythmia or ischemia.",
      "action_type": "monitored",
      "target": "cardiac rhythm"
    },
    {
      "text": "Reassess pain and continue to monitor response to ondansetron for nausea, with pain reported as mild to moderate (up to 5/10).",
      "action_type": "assessment_performed",
      "target": "pain and nausea"
    },
    {
      "text": "Perform a fall risk reassessment and implement fall precautions given weak gait/transferring and bed rest status.",
      "action_type": "assessment_performed",
      "target": "fall risk"
    },
    {
      "text": "Obtain a chest radiograph to evaluate for pulmonary source of infection or other cause of tachypnea and hypoxia.",
      "action_type": "imaging_performed",
      "target": "chest radiograph"
    },
    {
      "text": "Monitor blood pressure closely with non-invasive cuff and reassess need for antihypertensive therapy, as systolic BP ranged up to 145 mmHg with alarm limits.",
      "action_type": "monitored",
      "target": "blood pressure"
    },
    {
      "text": "Assess volume status and renal function with daily weights and basic metabolic panel, given creatinine 0.4 mg/dL and BUN 9 mg/dL.",
      "action_type": "assessment_performed",
      "target": "volume and renal status"
    },
    {
      "text": "Continue venous thromboembolism prophylaxis with subcutaneous heparin 5000 units as ordered.",
      "action_type": "therapy_continued",
      "target": "VTE prophylaxis"
    },
    {
      "text": "Maintain IV access and continue to monitor for need for fluid resuscitation or medication administration via existing IV.",
      "action_type": "monitored",
      "target": "IV access"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue continuous pulse oximetry monitoring with the low SpO2 alarm set at 92% and desaturation limit at 85%, given current O2 flow of 2 L/min and SpO2 99-100%.",
      "action_type": "monitored",
      "target": "oxygen saturation"
    },
    {
      "text": "Continue cardiac monitoring with ST segment monitoring and heart rate alarms (high 120, low 60) given prior tachycardia and current heart rate 75-91 bpm.",
      "action_type": "monitored",
      "target": "heart rate and rhythm"
    },
    {
      "text": "Continue non-invasive blood pressure monitoring with high/low alarms (160/90 mmHg) given prior blood pressure variability and current BP 94-115/54-74 mmHg.",
      "action_type": "monitored",
      "target": "blood pressure"
    },
    {
      "text": "Assess and manage moderate pain (reported 5/10, mild-moderate 3/10) with the existing PRN oxycodone and ketorolac orders, reassessing response.",
      "action_type": "assessment_performed",
      "target": "pain"
    },
    {
      "text": "Recheck serum magnesium given initial hypomagnesemia (1.5 mg/dL) and subsequent magnesium sulfate administration, to confirm normalization (last 2.8 mg/dL).",
      "action_type": "specimen_collected",
      "target": "serum magnesium"
    },
    {
      "text": "Monitor blood glucose given fingerstick 161 mg/dL and serum glucose 146-152 mg/dL, with hypoglycemia protocol range 70-100 mg/dL.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Continue venous thromboembolism and mobility precautions: bed rest with IV saline lock, Braden activity bedfast, and fall risk precautions.",
      "action_type": "ordered",
      "target": "fall and immobility precautions"
    },
    {
      "text": "Continue bowel regimen with docusate and bisacodyl as ordered, monitoring bowel function.",
      "action_type": "therapy_continued",
      "target": "bowel regimen"
    },
    {
      "text": "Continue monitoring for anxiety/agitation (RASS +1) and provide reassurance/environmental measures; PRN lorazepam and hydroxyzine are available if needed.",
      "action_type": "monitored",
      "target": "anxiety and agitation"
    },
    {
      "text": "Maintain current respiratory support with 2 L/min nasal cannula and monitor respiratory rate (alarms high 35/low 8), currently 16-20 insp/min.",
      "action_type": "therapy_continued",
      "target": "oxygen therapy"
    }
  ]
}

{
  "claims": [
    {
      "text": "Reassess and manage hypotension (recent systolic BP 89-99 mmHg, MAP 62-67 mmHg) with fluid resuscitation and hemodynamic monitoring.",
      "action_type": "monitored",
      "target": "hemodynamic status"
    },
    {
      "text": "Continue broad-spectrum antibiotics (levofloxacin, metronidazole, oral vancomycin) and monitor for clinical improvement given leukocytosis (WBC up to 27.9 K/uL).",
      "action_type": "therapy_continued",
      "target": "infection treatment"
    },
    {
      "text": "Repeat basic metabolic panel and magnesium to reassess hyponatremia (Na 128-133 mEq/L), hypocalcemia (total Ca 7.0-7.8 mg/dL), and prior hypomagnesemia.",
      "action_type": "specimen_collected",
      "target": "serum electrolytes and magnesium"
    },
    {
      "text": "Monitor oxygen saturation and respiratory status on 4 L/min nasal cannula, with SpO2 desaturation limit set at 85-88%.",
      "action_type": "monitored",
      "target": "oxygenation and respiratory status"
    },
    {
      "text": "Reassess pain and continue multimodal analgesia as needed (recent pain level mild to moderate).",
      "action_type": "assessment_performed",
      "target": "pain"
    },
    {
      "text": "Implement fall precautions and maintain bed rest given high fall risk (history of falls, bedfast, IV access).",
      "action_type": "ordered",
      "target": "fall prevention"
    },
    {
      "text": "Perform aspiration precautions and oral care given mildly impaired swallow and increased secretions.",
      "action_type": "ordered",
      "target": "aspiration precautions"
    },
    {
      "text": "Monitor hemoglobin/hematocrit (Hgb 9.3-10.2 g/dL, Hct 28.7-32.3%) and transfuse if clinically indicated.",
      "action_type": "monitored",
      "target": "hemoglobin and hematocrit"
    },
    {
      "text": "Recheck lactate (recent 2.4 mmol/L) to assess for ongoing hypoperfusion.",
      "action_type": "specimen_collected",
      "target": "serum lactate"
    },
    {
      "text": "Continue venous thromboembolism prophylaxis with subcutaneous heparin 5000 units.",
      "action_type": "therapy_continued",
      "target": "VTE prophylaxis"
    }
  ]
}

{
  "claims": [
    {
      "text": "Initiate or continue broad-spectrum empiric antibiotic therapy for suspected severe infection/sepsis, given leukocytosis (WBC 28.5-36.8 K/uL) and bandemia.",
      "action_type": "ordered",
      "target": "empiric broad-spectrum antibiotics"
    },
    {
      "text": "Maintain vasopressor support with phenylephrine infusion for hypotension (NIBP 71/58, MAP 62), titrating to MAP goal.",
      "action_type": "therapy_continued",
      "target": "phenylephrine infusion"
    },
    {
      "text": "Obtain repeat lactate measurement to assess clearance and resuscitation response, given elevated lactate 3.1-4.4 mmol/L.",
      "action_type": "specimen_collected",
      "target": "serum lactate"
    },
    {
      "text": "Obtain serial troponin and CK-MB measurements and continuous ECG monitoring for evolving myocardial injury (troponin T rising to 3.75 ng/mL, CK-MB 170 ng/mL).",
      "action_type": "monitored",
      "target": "cardiac biomarkers and telemetry"
    },
    {
      "text": "Perform focused assessment for sepsis source, including review of urinalysis showing pyuria/bacteriuria and consideration of chest imaging.",
      "action_type": "assessment_performed",
      "target": "sepsis source evaluation"
    },
    {
      "text": "Continue insulin therapy with hourly glucose monitoring for hyperglycemia (fingerstick glucose 292-371 mg/dL).",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Continue heparin infusion with monitoring of PTT and coagulation parameters, given elevated PTT 49.6 sec and ongoing anticoagulation.",
      "action_type": "monitored",
      "target": "PTT and coagulation status"
    },
    {
      "text": "Replete electrolytes as needed, including magnesium and potassium, with repeat basic metabolic panel to monitor sodium 129-131 mEq/L and bicarbonate 14-19 mEq/L.",
      "action_type": "monitored",
      "target": "electrolytes and acid-base status"
    },
    {
      "text": "Maintain supplemental oxygen and monitor SpO2, given desaturation to 84% and current O2 flow 3 L/min.",
      "action_type": "monitored",
      "target": "oxygen saturation"
    },
    {
      "text": "Continue venous thromboembolism prophylaxis and monitor for bleeding, given immobility (bedrest) and anticoagulation.",
      "action_type": "therapy_continued",
      "target": "VTE prophylaxis"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain a repeat complete blood count to confirm and trend the anemia (hemoglobin 7.7 g/dL, hematocrit 27.6%) and leukopenia (WBC 2.4 K/uL).",
      "action_type": "specimen_collected",
      "target": "complete blood count"
    },
    {
      "text": "Monitor for signs of anemia-related end-organ hypoperfusion and check for occult bleeding, given hemoglobin 7.7 g/dL and hematocrit 27.6%.",
      "action_type": "monitored",
      "target": "anemia and bleeding"
    },
    {
      "text": "Assess and manage alcohol withdrawal with symptom-triggered CIWA monitoring, given history of ETOH use and fluctuating tremor/CIWA scores.",
      "action_type": "assessment_performed",
      "target": "alcohol withdrawal"
    },
    {
      "text": "Continue thiamine supplementation for alcohol-use-related nutritional risk.",
      "action_type": "therapy_continued",
      "target": "thiamine"
    },
    {
      "text": "Continue folic acid supplementation.",
      "action_type": "therapy_continued",
      "target": "folic acid"
    },
    {
      "text": "Monitor and replete electrolytes, including potassium 3.4 mEq/L, magnesium 1.8 mg/dL, and phosphate 2.6 mg/dL.",
      "action_type": "monitored",
      "target": "electrolytes"
    },
    {
      "text": "Monitor blood glucose and manage hyperglycemia, given fingerstick glucose values of 208 and 294 mg/dL.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Assess and manage the mildly elevated anion gap metabolic profile (anion gap 11 mEq/L, bicarbonate 21 mEq/L).",
      "action_type": "assessment_performed",
      "target": "acid-base status"
    },
    {
      "text": "Maintain fall precautions and delirium monitoring, given fluctuating mental status and fall-risk factors.",
      "action_type": "monitored",
      "target": "falls and delirium"
    },
    {
      "text": "Continue maintenance intravenous fluids (D5NS at 5 mL/hour).",
      "action_type": "therapy_continued",
      "target": "intravenous fluids"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain repeat arterial blood gas to reassess hypercapnic respiratory acidosis (pH 7.25-7.27, pCO2 54-55) and guide ventilatory support.",
      "action_type": "specimen_collected",
      "target": "arterial blood gas"
    },
    {
      "text": "Maintain close monitoring of respiratory status including continuous pulse oximetry and frequent respiratory rate checks given hypercapnia and tachypnea risk.",
      "action_type": "monitored",
      "target": "respiratory status"
    },
    {
      "text": "Continue supplemental oxygen therapy titrated to maintain SpO2 above 88-92% desaturation limit.",
      "action_type": "therapy_continued",
      "target": "supplemental oxygen"
    },
    {
      "text": "Recheck serum magnesium given prior hypomagnesemia (1.5 mg/dL) and active magnesium repletion to confirm normalization.",
      "action_type": "specimen_collected",
      "target": "serum magnesium"
    },
    {
      "text": "Monitor blood pressure closely given hypotension (arterial BP 91/78, mean 84) and adjust vasoactive or fluid therapy as needed.",
      "action_type": "monitored",
      "target": "blood pressure"
    },
    {
      "text": "Continue epidural analgesia infusion and monitor pain control and sensory/motor function.",
      "action_type": "therapy_continued",
      "target": "epidural analgesia"
    },
    {
      "text": "Continue PCA hydromorphone for pain management and monitor PCA usage and pain scores.",
      "action_type": "therapy_continued",
      "target": "PCA hydromorphone"
    },
    {
      "text": "Perform daily assessment of Braden score and implement pressure injury prevention measures (skin care, repositioning).",
      "action_type": "assessment_performed",
      "target": "pressure injury risk"
    },
    {
      "text": "Encourage incentive spirometry and cough/deep breathing exercises to prevent atelectasis and support ventilation.",
      "action_type": "therapy_continued",
      "target": "incentive spirometry"
    },
    {
      "text": "Monitor blood glucose given hyperglycemia (130-131 mg/dL) and active insulin therapy.",
      "action_type": "monitored",
      "target": "blood glucose"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue mechanical ventilation with lung-protective settings and monitor respiratory status, including ABG and ventilator parameters.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Continue sedation with fentanyl and propofol infusions to maintain goal RASS -1, and monitor sedation level.",
      "action_type": "therapy_continued",
      "target": "sedation (fentanyl/propofol)"
    },
    {
      "text": "Monitor and manage severe metabolic acidosis with elevated lactate; consider serial lactate and ABG checks and evaluate for underlying causes.",
      "action_type": "monitored",
      "target": "metabolic acidosis and lactate"
    },
    {
      "text": "Monitor coagulation parameters (INR, PT, PTT, fibrinogen, platelets) given coagulopathy and thrombocytopenia; assess bleeding risk.",
      "action_type": "monitored",
      "target": "coagulation status"
    },
    {
      "text": "Monitor liver function tests and bilirubin given hyperbilirubinemia and elevated transaminases.",
      "action_type": "monitored",
      "target": "liver function"
    },
    {
      "text": "Monitor hemoglobin/hematocrit and assess need for transfusion given anemia.",
      "action_type": "monitored",
      "target": "hemoglobin/hematocrit"
    },
    {
      "text": "Monitor electrolytes (ionized calcium, magnesium, potassium) and replace as needed.",
      "action_type": "monitored",
      "target": "electrolytes"
    },
    {
      "text": "Perform daily sedation interruption and spontaneous breathing trial assessment to evaluate readiness for extubation.",
      "action_type": "assessment_performed",
      "target": "sedation and weaning readiness"
    },
    {
      "text": "Provide stress ulcer prophylaxis and monitor for GI bleeding given coagulopathy and mechanical ventilation.",
      "action_type": "ordered",
      "target": "stress ulcer prophylaxis"
    },
    {
      "text": "Provide venous thromboembolism prophylaxis, considering bleeding risk, and monitor.",
      "action_type": "ordered",
      "target": "VTE prophylaxis"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue renal replacement therapy (CRRT) for acute kidney injury with severe azotemia, hyperphosphatemia, and metabolic acidosis.",
      "action_type": "therapy_continued",
      "target": "renal replacement therapy"
    },
    {
      "text": "Continue mechanical ventilation with lung-protective settings, weaning toward spontaneous breathing as tolerated.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Continue norepinephrine infusion to maintain adequate mean arterial pressure.",
      "action_type": "therapy_continued",
      "target": "norepinephrine infusion"
    },
    {
      "text": "Monitor arterial blood gases and lactate to assess acid-base status and perfusion.",
      "action_type": "monitored",
      "target": "arterial blood gases and lactate"
    },
    {
      "text": "Monitor platelet count and coagulation parameters for thrombocytopenia and bleeding risk.",
      "action_type": "monitored",
      "target": "platelet count and coagulation"
    },
    {
      "text": "Monitor serum potassium and magnesium and replace as needed to maintain normal levels.",
      "action_type": "monitored",
      "target": "serum potassium and magnesium"
    },
    {
      "text": "Monitor blood glucose closely and continue insulin therapy to manage hyperglycemia.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Monitor for rhabdomyolysis complications (acute kidney injury, hyperkalemia, hyperphosphatemia) with serial creatine kinase and renal function tests.",
      "action_type": "monitored",
      "target": "creatine kinase and renal function"
    },
    {
      "text": "Perform daily sedation interruption and delirium assessment (CAM-ICU) to guide sedation management.",
      "action_type": "assessment_performed",
      "target": "sedation and delirium"
    },
    {
      "text": "Obtain blood cultures and administer broad-spectrum antibiotics for suspected infection given leukocytosis and fever.",
      "action_type": "ordered",
      "target": "blood cultures and antibiotics"
    }
  ]
}

{
  "claims": [
    {
      "text": "Monitor serum potassium closely and treat hyperkalemia, given potassium 6.2 mEq/L and active potassium chloride infusion.",
      "action_type": "monitored",
      "target": "serum potassium"
    },
    {
      "text": "Continue mechanical ventilation with lung-protective settings and monitor airway pressures and oxygenation.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Maintain phenylephrine infusion and monitor hemodynamics given borderline blood pressures (MAP ~60 mmHg).",
      "action_type": "therapy_continued",
      "target": "phenylephrine infusion"
    },
    {
      "text": "Continue insulin infusion and monitor blood glucose.",
      "action_type": "therapy_continued",
      "target": "insulin infusion"
    },
    {
      "text": "Assess and manage pain, with PRN analgesics as ordered, given reported worst pain 10.",
      "action_type": "assessment_performed",
      "target": "pain"
    },
    {
      "text": "Monitor hemoglobin and hematocrit for anemia and consider transfusion if clinically indicated.",
      "action_type": "monitored",
      "target": "hemoglobin/hematocrit"
    },
    {
      "text": "Continue temporary pacemaker with monitoring of settings and rhythm.",
      "action_type": "therapy_continued",
      "target": "temporary pacemaker"
    },
    {
      "text": "Monitor coagulation parameters (INR, PTT, fibrinogen) given elevated INR and low fibrinogen.",
      "action_type": "monitored",
      "target": "coagulation parameters"
    },
    {
      "text": "Perform regular neurologic assessments including sedation scale and delirium screening.",
      "action_type": "assessment_performed",
      "target": "neurologic status"
    },
    {
      "text": "Implement aspiration precautions and oral care given intubation and subglottic suctioning.",
      "action_type": "treatment_performed",
      "target": "aspiration precautions"
    }
  ]
}

{
  "claims": [
    {
      "text": "Transfuse packed red blood cells for severe anemia (hemoglobin 6.8 g/dL, consent documented).",
      "action_type": "ordered",
      "target": "packed red blood cells"
    },
    {
      "text": "Assess and manage hypotension (MAP 65 mmHg, SBP 81 mmHg) with fluid resuscitation and vasopressor titration.",
      "action_type": "assessment_performed",
      "target": "hemodynamic status"
    },
    {
      "text": "Continue mechanical ventilation with lung-protective settings, targeting SpO2 92-96% and avoiding hyperoxia.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Monitor arterial blood gases and lactate to assess oxygenation and perfusion.",
      "action_type": "monitored",
      "target": "arterial blood gases and lactate"
    },
    {
      "text": "Monitor hemoglobin and hematocrit to assess response to transfusion.",
      "action_type": "monitored",
      "target": "hemoglobin and hematocrit"
    },
    {
      "text": "Check and replete electrolytes, including potassium and magnesium, as needed.",
      "action_type": "monitored",
      "target": "electrolytes"
    },
    {
      "text": "Continue insulin infusion with hourly glucose monitoring to maintain glucose 70-100 mg/dL.",
      "action_type": "therapy_continued",
      "target": "insulin infusion and glucose monitoring"
    },
    {
      "text": "Monitor platelet count and coagulation parameters given thrombocytopenia and coagulopathy.",
      "action_type": "monitored",
      "target": "platelet count and coagulation"
    },
    {
      "text": "Perform chest imaging to evaluate pulmonary status and line positions.",
      "action_type": "imaging_performed",
      "target": "chest radiograph"
    },
    {
      "text": "Maintain temporary pacemaker settings and monitor rhythm.",
      "action_type": "therapy_continued",
      "target": "temporary pacemaker"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue targeted temperature management at 35°C per Arctic Sun set temperature, with ongoing shivering assessment.",
      "action_type": "therapy_continued",
      "target": "Arctic Sun targeted temperature management"
    },
    {
      "text": "Continue mechanical ventilation in APV (CMV) mode with set tidal volume 450 mL, PEEP 5 cmH2O, FiO2 50%, and respiratory rate 15/min.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Continue propofol infusion for sedation targeting RASS -5.",
      "action_type": "therapy_continued",
      "target": "propofol infusion"
    },
    {
      "text": "Continue fentanyl infusion for analgesia.",
      "action_type": "therapy_continued",
      "target": "fentanyl infusion"
    },
    {
      "text": "Continue norepinephrine infusion and monitor blood pressure to maintain hemodynamic stability.",
      "action_type": "therapy_continued",
      "target": "norepinephrine infusion"
    },
    {
      "text": "Monitor arterial blood gases and lactate to assess oxygenation, ventilation, and perfusion.",
      "action_type": "monitored",
      "target": "arterial blood gas and lactate"
    },
    {
      "text": "Monitor blood glucose given recent fingerstick values of 114-148 mg/dL and insulin/dextrose therapy.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Monitor coagulation panel (PT/INR/PTT) given prolonged PTT 80-94.5 sec and heparin infusion.",
      "action_type": "monitored",
      "target": "coagulation panel"
    },
    {
      "text": "Monitor serum potassium and magnesium given active electrolyte replacement and recent K 3.7 mEq/L.",
      "action_type": "monitored",
      "target": "serum electrolytes"
    },
    {
      "text": "Maintain endotracheal tube cuff pressure within target range (recent 26-29 cmH2O) and continue subglottal suctioning.",
      "action_type": "monitored",
      "target": "endotracheal tube cuff pressure"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue lung-protective mechanical ventilation with low tidal volumes and monitor respiratory mechanics and oxygenation.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Continue propofol and fentanyl infusions to maintain sedation and analgesia, targeting RASS -2 to -1.",
      "action_type": "therapy_continued",
      "target": "sedation and analgesia"
    },
    {
      "text": "Continue piperacillin-tazobactam and vancomycin for presumed infection, with cultures obtained.",
      "action_type": "therapy_continued",
      "target": "antimicrobial therapy"
    },
    {
      "text": "Monitor renal function with serial creatinine and urine output, avoiding nephrotoxins.",
      "action_type": "monitored",
      "target": "renal function"
    },
    {
      "text": "Replete potassium and magnesium as needed to maintain normal levels.",
      "action_type": "ordered",
      "target": "electrolyte replacement"
    },
    {
      "text": "Monitor temperature and obtain cultures if fever persists.",
      "action_type": "monitored",
      "target": "temperature"
    },
    {
      "text": "Continue enteral nutrition via feeding tube as tolerated.",
      "action_type": "therapy_continued",
      "target": "enteral nutrition"
    },
    {
      "text": "Perform chest imaging to evaluate pulmonary status.",
      "action_type": "imaging_performed",
      "target": "chest imaging"
    },
    {
      "text": "Perform daily assessment of sedation and delirium using RASS and CAM-ICU.",
      "action_type": "assessment_performed",
      "target": "sedation and delirium"
    },
    {
      "text": "Maintain head-of-bed elevation and subglottal suctioning to prevent ventilator-associated pneumonia.",
      "action_type": "therapy_continued",
      "target": "VAP prevention"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue mechanical ventilation with current settings, monitoring for weaning readiness as patient is on CPAP/PSV with spontaneous breathing.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Monitor arterial blood gases and oxygen saturation to assess ventilation and oxygenation status.",
      "action_type": "monitored",
      "target": "arterial blood gases and oxygen saturation"
    },
    {
      "text": "Monitor hemoglobin and hematocrit given anemia (Hgb 8-10.4 g/dL) and assess need for transfusion.",
      "action_type": "monitored",
      "target": "hemoglobin and hematocrit"
    },
    {
      "text": "Monitor platelet count given thrombocytopenia (101-146 K/uL) and assess bleeding risk.",
      "action_type": "monitored",
      "target": "platelet count"
    },
    {
      "text": "Monitor serum electrolytes (sodium, potassium, chloride, bicarbonate) and renal function (creatinine, BUN).",
      "action_type": "monitored",
      "target": "serum electrolytes and renal function"
    },
